SELECT grade FROM Highschooler WHERE ID IN (
    SELECT student_id FROM Friend GROUP BY student_id HAVING COUNT(*) >= 4
);

SELECT name FROM Highschooler WHERE ID NOT IN (
	SELECT student_id FROM Friend
	UNION ALL
	SELECT friend_id FROM Friend
);

SELECT name FROM Highschooler WHERE ID IN (
    SELECT student_id FROM Friend
    UNION ALL
    SELECT friend_id FROM Friend
) AND ID IN (
    SELECT liked_id FROM Likes
    INTERSECT
    SELECT student_id FROM Likes
);

SELECT name FROM Highschooler WHERE ID IN (
    SELECT student_id FROM Likes
    UNION ALL
    SELECT liked_id FROM Likes
);

SELECT PetType, AVG(weight) as AverageWeight
FROM Pets
GROUP BY PetType;

SELECT Abbreviation, Country FROM airlines WHERE uid = (
    SELECT Airline FROM (
        SELECT Airline, COUNT(*) AS flight_count FROM flights GROUP BY Airline ORDER BY flight_count LIMIT 1
    ) t
);

SELECT PetType, AVG(weight) as AverageWeight
FROM Pets
GROUP BY PetType;

SELECT PetType, AVG(Age), MAX(Age)
FROM Student AS S JOIN Has_Pet AS HP ON S.StuID = HP.StuID JOIN Pets AS P ON HP.PetID = P.PetID
GROUP BY PetType;

SELECT Directed_by, COUNT(*) as Number_of_Cartoons
FROM Cartoon
GROUP BY Directed_by;

SELECT CountryName FROM countries WHERE Continent = 'Europe' AND CountryId IN (
    SELECT CountryId FROM car_makers GROUP BY CountryId HAVING COUNT(Id) >= 3
);

SELECT Template_Type_Code FROM Templates WHERE Template_ID IN (
    SELECT Template_ID FROM Documents GROUP BY Template_ID ORDER BY COUNT(*) DESC LIMIT 1
);

SELECT MAX(winner_rank) 
FROM matches AS m 
JOIN players AS w ON m.winner_id = w.player_id;

SELECT winner_name, winner_rank_points FROM players WHERE player_id = (
  SELECT winner_id FROM matches GROUP BY winner_id ORDER BY COUNT(*) DESC LIMIT 1
);

SELECT T1.winner_name AS winner, T2.loser_name AS loser 
FROM matches AS T1 
JOIN players AS T2 ON T1.winner_id = T2.player_id 
WHERE (T1.tournament_name, T1.year) IN (
  SELECT tournament_name, year FROM matches GROUP BY tournament_name, year ORDER BY COUNT(*) DESC LIMIT 1
);

SELECT winner_name, winner_rank FROM players WHERE player_id IN (
  SELECT winner_id FROM matches ORDER BY winner_age ASC LIMIT 3
);

SELECT loser_name, winner_name 
FROM matches 
WHERE (loser_id, winner_id) IN (
  SELECT loser_id, winner_id FROM matches 
  ORDER BY minutes DESC LIMIT 1
);

SELECT p.winner_name FROM players p JOIN (
  SELECT w.player_id, MAX(r.ranking_points) AS max_points 
  FROM rankings r JOIN players w ON r.player_id = w.player_id 
  WHERE r.tours = 'Australian Open' 
  GROUP BY w.player_id
) t ON p.player_id = t.player_id;

SELECT T1.first_name, T1.country_code FROM players AS T1 JOIN (
    SELECT winner_id FROM matches WHERE tournament_name IN ('WTA Championships', 'Australian Open')
) AS T2 ON T1.player_id = T2.winner_id;

SELECT T1.country_code, T1.first_name FROM players AS T1 JOIN (
  SELECT winner_id FROM matches WHERE tournament_name IN ('WTA Championships', 'Australian Open')
) AS T2 ON T1.player_id = T2.winner_id AND T1.tournament_name IN ('WTA Championships', 'Australian Open');

SELECT T1.first_name, T1.country_code, T1.birth_date FROM players AS T1 JOIN (
    SELECT winner_id, MAX(winner_rank_points) as max_points 
    FROM rankings 
    GROUP BY winner_id
) AS T2 ON T1.player_id = T2.winner_id;

SELECT Code 
FROM country 
WHERE GovernmentForm != 'Republic' AND Language != 'English';

SELECT COUNT(*) 
FROM Dogs d 
JOIN Treatments t ON d.dog_id = t.dog_id;

SELECT AVG(T.age) 
FROM Dogs AS T 
JOIN Treatments AS S ON T.dog_id = S.dog_id;

SELECT COUNT(DISTINCT T1.student_enrolment_id) AS max_transcripts, T1.student_enrolment_id FROM Student_Enrolment CTE 
JOIN Transcript_Contents CT ON CTE.student_course_id = CT.student_course_id 
GROUP BY CTE.student_enrolment_id;
